mapper.update:
update tb_approval_master
   set status = #{status}
 where id = #{id}

mapper.insert:
insert into tb_approval_line (
     approval_id
    ,approver_id
    ,sequence
    ,type
    ,status
    ,is_approve
)
values(
     #{approval_id}
    ,#{approver_id}
    ,CAST(#{sequence} AS INTEGER)
    ,#{type}
    ,#{status}
    ,#{is_approve}
);

mapper.update:
DO $$ DECLARE v_current_sequence INT; BEGIN select sequence + 1 as new_sequence into v_current_sequence from tb_approval_line where 1=1 and approval_id = '${approval_id}' and is_approve = '1';
update tb_approval_line set status = ${status} ,comment = '${comment}' ,is_approve = '0' ,approved_at = now() where 1=1 and approval_id = '${approval_id}' and approver_id = '${approver_id}';
update tb_approval_line set is_approve = '1' where 1=1 and approval_id = '${approval_id}' and sequence = v_current_sequence; END $$;

mapper.select:
select max(sequence) as last_sequence
  from tb_approval_line
 where approval_id = #{approval_id}

select sequence as approver_seq
  from tb_approval_line
 where approval_id = #{approval_id}
   and approver_id = #{approver_id}
